{
  "bbb_prediction": "fail",
  "claims": [
    {
      "card_ids": ["C05"],
      "claim": "Cetirizine, a close zwitterionic second-generation antihistamine with a carboxylic acid and basic amine, showed only 19.4% brain uptake in rats and was classified as low permeability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C03"],
      "claim": "Cetirizine's very low brain concentration after intravenous administration was attributed to P-gp-mediated efflux at the BBB, a liability shared by the query's acid/amine zwitterion.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C12"],
      "claim": "In mice, cetirizine brain-to-free plasma ratios were 0.16-0.49, indicating impaired brain penetration even after correcting for plasma protein binding.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C19"],
      "claim": "Bepotastine, a piperidine-containing second-generation antihistamine with a carboxylic acid side chain, showed only 16.6% cortical H1 receptor occupancy by PET in humans, indicating slight/low BBB penetration.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C06"],
      "claim": "Levocetirizine had the lowest cerebral H1 receptor occupancy among antihistamines by PET, consistent with low BBB crossing for this zwitterionic class.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C09"],
      "claim": "PET in volunteers showed cetirizine can cross the BBB and bind approximately 30% of cortical H1 receptors, indicating measurable but limited CNS exposure.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is a fexofenadine-like zwitterionic antihistamine with a carboxylic acid and basic piperidine. Direct evidence from close analogues (cetirizine, levocetirizine, bepotastine) shows low brain uptake, low H1 receptor occupancy, and P-gp-mediated efflux; the physicochemical prior is also unfavorable. The limited PET signal for cetirizine does not overcome the consistent low/efflux-limited CNS access pattern, so the query is predicted to lack meaningful CNS access.",
  "evidence_gaps": [
    "No direct brain, CSF, or PET measurement for the query molecule itself in the provided evidence.",
    "Morgan similarities to the closest evidence molecules are modest (0.28-0.33), so transfer relies on shared zwitterionic antihistamine pharmacophore and transporter biology.",
    "Species differences in transporter expression and plasma protein binding could alter quantitative brain exposure."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

